/ {
    i2c_emul: i2c_emul_0 {
        compatible = "i2c-emul";
        #address-cells = <1>;
        #size-cells = <0>;
        status = "okay";

        adt7420_0: adt7420@48 {
            compatible = "adi,adt7420";
            reg = <0x48>;
            status = "okay";
            label = "ADT7420_0";
        };
    };
};
